SET NOCOUNT ON; SET LOCK_TIMEOUT 2000;
SELECT COUNT_BIG(*) AS NewRoleClaimAuditRows, COUNT_BIG(i.LogicalId) AS WithIdentityReceipt, MIN(a.CreatedAt) AS FirstCreatedUtc, MAX(a.CreatedAt) AS LastCreatedUtc
FROM audit.AuditLogs a LEFT JOIN audit.AuditEnvelopeIdentities i ON i.LogicalId=a.EnvelopeId AND i.Channel='entity'
WHERE a.CreatedAt >= '2026-10-17T14:39:37' AND a.EntityType='IdentityRoleClaim`1' AND a.Action=1
FOR JSON PATH, WITHOUT_ARRAY_WRAPPER;
